<script setup lang="ts">import{onMounted}from'vue';import{Heart,Plus}from'lucide-vue-next';import{useRoute,useRouter}from'vue-router';import type{Product}from'@/types';import PriceDisplay from'./PriceDisplay.vue';import{useCartStore}from'@/stores/cart';import{useToastStore}from'@/stores/toast';import{useAuthStore}from'@/stores/auth';import{useFavoritesStore}from'@/stores/favorites';const props=defineProps<{product:Product}>(),cart=useCartStore(),toast=useToastStore(),auth=useAuthStore(),favorites=useFavoritesStore(),router=useRouter(),route=useRoute();function add(p:Product){cart.add(p);toast.show(`${p.name} added to bag`)}async function toggleFavorite(){if(!auth.user){toast.show('Sign in to save favorites','error');await router.push({name:'login',query:{redirect:route.fullPath}});return}try{await favorites.toggle(auth.user.id,props.product);toast.show(favorites.has(props.product.id)?'Saved to favorites':'Removed from favorites')}catch(e){toast.show(e instanceof Error?e.message:'Could not update favorites','error')}}onMounted(()=>{if(auth.user)void favorites.fetchAll(auth.user.id).catch(()=>undefined)})</script>
<template><article class="product-card"><RouterLink :to="`/product/${product.slug}`" class="product-card__image"><img :src="product.image_url||'/placeholder.svg'" :alt="product.name"><span v-if="product.old_price" class="pill">Sale</span><button class="icon-button favorite" :class="{active:favorites.has(product.id)}" :aria-label="favorites.has(product.id)?'Remove from favorites':'Add to favorites'" @click.prevent.stop="toggleFavorite"><Heart :size="18" :fill="favorites.has(product.id)?'currentColor':'none'"/></button></RouterLink><div class="product-card__meta"><p>{{product.category?.name}}</p><h3><RouterLink :to="`/product/${product.slug}`">{{product.name}}</RouterLink></h3><div class="product-card__bottom"><PriceDisplay :price="product.price" :old-price="product.old_price"/><button class="icon-button add" :disabled="!product.stock" aria-label="Add to cart" @click="add(product)"><Plus :size="18"/></button></div></div></article></template>
